-- 铭镓半导体 纳入研究池；TREE.material 新增 leaf「氧化镓衬底」(2026-10-16)

INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'铭镓半导体',null,'semiconductor','material',false,'Pre-B 轮',null,9.1,null,'2026-07','{"name":"铭镓半导体","industry":"semiconductor","seg":"material","listed":false,"desc":"北京铭镓半导体有限公司（2020-11-20 成立，总部北京市顺义区顺强路 1 号），法定代表人、董事长兼 CEO 陈政委（日本国立佐贺大学工学博士，专攻氧化镓材料与器件，发表论文 30 余篇）。公司专注新型半导体人工晶体材料，是国内第一家将半导体氧化镓材料产业化落地的企业，也是国内少数同时生产磷化铟晶体与大尺寸掺杂光学晶体的企业之一。三大产品线：① 氧化镓（Ga2O3）单晶衬底及外延片——第四代超宽禁带半导体，具备本征日盲紫外波段、耐高压、低损耗、高功率、高频率、耐高温与化学稳定性好等特性；② 磷化铟（InP）多晶及单晶——直接带隙、电子饱和漂移速度高，是 6G 通信、雷达、激光器与光电集成的基础材料，公司磷化铟多晶月产能超 1.5 吨、国内市场占有率稳居第一、订单排期已延伸至 2027 年底；③ 大尺寸掺杂光学晶体——莫氏硬度 9 级、透光率高达 95%、可在 1900℃ 高温稳定工作。公司已搭建晶体生长、晶体加工、外延薄膜、性能测试、微纳加工、联合研发六大平台，产线超 30000 平方米（含 3000 平方米研发中试产线），员工近 100 人，核心团队来自日本国立佐贺大学、东京大学、清华大学、九州大学、中国科学院及博蓝特、露笑科技、有研材料、中芯国际、美国通美等企业与院所。技术进展：4 英寸氧化镓衬底已稳定量产，已具备 6 英寸氧化镓从单晶衬底到外延片的完整研发生产能力，在第四代半导体领域积累 80 余项自主知识产权与专利；运用新工艺成功制备 4 英寸 (010) 相高质量氧化镓晶坯，为全球首次。产能规划：增扩 4-6 英寸氧化镓中试产线设备 20 台（套），达产后氧化镓衬底产能达 3 万片；磷化铟多晶设备由 2025 年 30 台扩至 2026 年上半年 80 台、年底 200 台，达产后年产近 50 吨；上游原料由蓝晓科技长期稳定供应。客户已进入华为、中际旭创等供应链。经营业绩：2025 年实现产值 3000 万元、营收 2500 万元，预计 2026 年产值与营收双破亿元；2025 年获顺义区第三代半导体重点支持项目资金 5000 余万元。公司同时是氧化镓领域龙头企业与北京市唯一聚焦超宽禁带半导体的育新平台，开放 3000 平方米实验平台及 50 余套精密设备，并依托博士后科研工作站组建北京市高校院所联合研发小组。荣誉：中关村高新技术企业、2022 年国家高新技术企业、2022 年北京市创新型中小企业、2023 年北京市专精特新中小企业、ITEC2022 全球创业赛初创组一等奖、第十一届中国创新创业大赛北京赛区成长组二等奖、2020 HICOOL 大赛三等奖。总部外设全资子公司于河南安阳、山东济南、广东深圳，并在义乌、上海、广州、南昌设立业务办事处。","valuation":9.1,"round":"Pre-B 轮","lastFunding":"2026-07","latestFunding":"Pre-B 轮 1.5 亿元人民币（2026-07-27），投资方为安阳经济开发集团、千曦资本、洪泰基金、粤科金融、天鹰资本、芯禾资本。此前 A++ 轮 1.1 亿元（2026-01-20）由彭程创投、成都科创投、天鹰资本、国煜基金及洪泰基金等联合注资，投后估值 9.1 亿元；该轮资金用于 6 英寸氧化镓衬底技术研发与量产、2-4 英寸氧化镓衬底中试产线建设、超宽禁带半导体未来产业培育及磷化铟多晶产线规模化扩产。","latestTech":"① 已具备 6 英寸氧化镓从单晶衬底到外延片的完整研发生产能力，4 英寸氧化镓衬底稳定量产；② 运用新工艺成功制备 4 英寸 (010) 相高质量氧化镓晶坯，为全球首次；③ 磷化铟多晶月产能超 1.5 吨、国内市占率第一，突破高压合成、精准控温、高纯提纯等核心技术；④ 氧化镓领域累计 80 余项自主知识产权与专利。","tech":[{"date":"2026-07","title":"完成 Pre-B 轮 1.5 亿元融资，扩产氧化镓与磷化铟双产线","kind":"融资","desc":"安阳经济开发集团等地方国资入场；磷化铟多晶设备年底扩至 200 台，达产后年产近 50 吨。"},{"date":"2026","title":"全球首次制备 4 英寸 (010) 相高质量氧化镓晶坯","kind":"技术","desc":"公司在巩固磷化铟领先地位的同时把目光投向更前沿的第四代半导体方向，已具备 6 英寸氧化镓从单晶衬底到外延片的完整研发生产能力。"},{"date":"2026-01","title":"完成 A++ 轮 1.1 亿元融资，投后估值 9.1 亿元","kind":"融资","desc":"资金投向 6 英寸氧化镓衬底技术研发与量产、2-4 英寸中试产线建设及磷化铟多晶产线扩产。"},{"date":"2022-03","title":"攻克 (001) 晶向氧化镓长晶","kind":"技术","desc":"公司最早攻克的 (100) 晶向虽长到 4-6 英寸但下游功率器件厂商不买单，2021 年全年攻关 (001) 晶向，2022 年 3 月晶体开始成型并从 10 毫米爬至 1 寸、2 寸。"}],"funding":[{"date":"2026-07","round":"Pre-B轮","amount":"1.5亿元","inv":"安阳经济开发集团、千曦资本、洪泰基金、粤科金融、天鹰资本、芯禾资本"},{"date":"2026-01","round":"A++轮","amount":"1.1亿元（投后估值9.1亿元）","inv":"彭程创投、成都科创投、天鹰资本、国煜基金、洪泰基金"},{"date":"2023-08","round":"A+轮","amount":"未披露","inv":"华控基金、瑞华控股、洪泰基金"},{"date":"2022-06","round":"A轮","amount":"近亿元","inv":"之路资本（领投）、允泰资本、分享投资、骆驼资本；穆棉资本担任独家财务顾问"},{"date":"2021-08","round":"Pre-A轮","amount":"数千万元","inv":"洪泰基金、分享投资、图灵创投"},{"date":"2021-02","round":"天使轮","amount":"千万元","inv":"创业大街投资、英诺天使基金、首科三新"}],"investorsStructured":[{"name":"洪泰基金","role":"strategic","round":"Pre-A/A+/A++/Pre-B","date":"2021-08","kind":"vc","note":"连续参与 4 轮，最长期机构股东"},{"name":"英诺天使基金","role":"lead","round":"天使轮","date":"2021-02","kind":"vc","note":"首家投资机构，尽调后三个月签约"},{"name":"之路资本","role":"lead","round":"A轮","date":"2022-06","kind":"vc","note":"背后有海外强大产业方支持的美元基金，走访日美论证后当年在国内仅投该项目"},{"name":"成都科创投","role":"follow","round":"A++轮","date":"2026-01","kind":"gov","note":"成都国资科创平台"},{"name":"天鹰资本","role":"follow","round":"A++/Pre-B","date":"2026-01","kind":"vc","note":"连续参与两轮"},{"name":"彭程创投","role":"lead","round":"A++轮","date":"2026-01","kind":"vc"},{"name":"国煜基金","role":"follow","round":"A++轮","date":"2026-01","kind":"vc"},{"name":"安阳经济开发集团","role":"lead","round":"Pre-B轮","date":"2026-07","kind":"gov","note":"安阳地方国资；公司在河南安阳设有全资子公司"},{"name":"粤科金融","role":"follow","round":"Pre-B轮","date":"2026-07","kind":"gov","note":"广东省属国资"},{"name":"千曦资本","role":"follow","round":"Pre-B轮","date":"2026-07","kind":"vc"},{"name":"芯禾资本","role":"follow","round":"Pre-B轮","date":"2026-07","kind":"vc","note":"半导体材料赛道专业基金"},{"name":"华控基金","role":"lead","round":"A+轮","date":"2023-08","kind":"pe","note":"清华控股背景"},{"name":"瑞华控股","role":"follow","round":"A+轮","date":"2023-08","kind":"pe"},{"name":"分享投资","role":"follow","round":"Pre-A/A轮","date":"2021-08","kind":"vc","note":"连续参与两轮"},{"name":"允泰资本","role":"follow","round":"A轮","date":"2022-06","kind":"vc"},{"name":"骆驼资本","role":"follow","round":"A轮","date":"2022-06","kind":"vc"},{"name":"图灵创投","role":"follow","round":"Pre-A轮","date":"2021-08","kind":"vc"},{"name":"首科三新","role":"follow","round":"天使轮","date":"2021-02","kind":"gov","note":"北京三新创业科技成果转化投资基金"},{"name":"中关村创业大街投资","role":"follow","round":"天使轮","date":"2021-02","kind":"gov"}],"executives":[{"name":"陈政委","title":"董事长兼 CEO","role":"board","bio":"2011 年毕业于天津工业大学，后赴日本国立佐贺大学攻读硕士、博士学位，2017 年获工学博士；就读期间专攻氧化镓材料与器件研发，发表相关论文 30 余篇，曾在九州同步光辐射中心从事宽禁带半导体外延薄膜及大型加速器材料物性解析工作。2020 年创立铭镓半导体，持股约 23.17%。入选 2020 年北京市高层次人才项目（第十五批次）、2021 年北京市顺义区梧桐工程高层次人才。","shares":"约 23.17%"},{"name":"王丹丹","title":"董事","role":"board","bio":"铭镓半导体董事，同时担任镓族科技董事。"}],"note":"国内氧化镓产业化先行者，商业逻辑为「以成熟材料养前沿材料」——用磷化铟多晶（国内市占率第一、订单排至 2027 年底）的现金流支撑氧化镓研发与产线。氧化镓成本约为 SiC 的三分之一、击穿电场强度约为 SiC 的两倍以上，同耐压下器件损耗较 SiC 基低约 86%、尺寸仅约 1/5，可采用熔体法生长；短板在导热差、P 型掺杂难与铱金坩埚成本。同赛道玩家：镓仁半导体（6/8 英寸同质外延量产线）、富加镓业（全球首发 8 英寸氧化镓晶体）、三安光电（A 股唯一打通氧化镓全流程 IDM，湖南基地 4 英寸量产）。与池内「谱析光晶」（SiC + 氧化镓特种功率芯片，清华电子系团队）形成材料与器件互补。"}'::jsonb,now()
)
